<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import AppIcon from '../../components/AppIcon.vue'
import { adminApi, publicApi } from '../../api/services.js'
import { useSeo } from '../../composables/useSeo.js'
import { useToast } from '../../composables/useToast.js'
import { formatDateTime, formatMoney, orderSourceLabel, orderStatusLabel, paymentStatusLabel } from '../../utils/format.js'

const route=useRoute(),toast=useToast(),order=ref(null),config=ref({shipping_methods:[],payment_methods:[]}),loading=ref(true),saving=ref(false),error=ref('')
const form=reactive({version:1,status:'new',payment_status:'unpaid',customer_name:'',customer_phone:'',customer_email:'',source:'website',shipping_method:'',shipping_city:'',shipping_branch:'',shipping_address:'',shipping_carrier:'',tracking_number:'',payment_method:'',customer_note:'',admin_note:'',discount_amount:0,shipping_amount:0,status_note:''})
const selectedShipping=computed(()=>config.value.shipping_methods?.find(x=>x.code===form.shipping_method)||null)
useSeo({title:'Order | Velmora Admin',description:'Order details.',path:route.path,noindex:true})
function assign(o){Object.assign(form,{version:o.version,status:o.status,payment_status:o.payment_status,customer_name:o.customer_name,customer_phone:o.customer_phone,customer_email:o.customer_email||'',source:o.source||'website',shipping_method:o.shipping_method||'',shipping_city:o.shipping_city||'',shipping_branch:o.shipping_branch||'',shipping_address:o.shipping_address||'',shipping_carrier:o.shipping_carrier||'',tracking_number:o.tracking_number||'',payment_method:o.payment_method||'',customer_note:o.customer_note||'',admin_note:o.admin_note||'',discount_amount:o.discount_minor/100,shipping_amount:o.shipping_minor/100,status_note:''})}
async function load(){loading.value=true;try{const [o,c]=await Promise.all([adminApi.order(route.params.id),publicApi.config()]);order.value=o;config.value=c;assign(o)}catch{error.value='Could not load the order.'}finally{loading.value=false}}
async function save(extra={}){if(!order.value)return;saving.value=true;error.value='';try{const payload={version:form.version,status:form.status,payment_status:form.payment_status,customer_name:form.customer_name,customer_phone:form.customer_phone,customer_email:form.customer_email||null,source:form.source,shipping_method:form.shipping_method||null,shipping_city:form.shipping_city||null,shipping_branch:form.shipping_branch||null,shipping_address:form.shipping_address||null,shipping_carrier:form.shipping_carrier||null,tracking_number:form.tracking_number||null,payment_method:form.payment_method||null,customer_note:form.customer_note||null,admin_note:form.admin_note||null,discount_minor:Math.round(Number(form.discount_amount||0)*100),shipping_minor:Math.round(Number(form.shipping_amount||0)*100),status_note:form.status_note||null,...extra};const updated=await adminApi.updateOrder(order.value.id,payload);order.value=updated;assign(updated);toast.show('Order updated.')}catch(e){if(e.response?.status===409){error.value='This order was changed by another user. Refresh the page.'}else error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:'Could not save changes.'}finally{saving.value=false}}
function shippingChanged(){const method=selectedShipping.value;if(!method)return;form.shipping_carrier=method.carrier||form.shipping_carrier;form.shipping_amount=(method.price_minor||0)/100}
async function quickStatus(status){form.status=status;await save({status})}
async function markPaid(){form.payment_status='paid';await save({payment_status:'paid'})}
onMounted(load)
</script>
<template><section class="admin-page"><div v-if="loading" class="admin-loading">Loading…</div><template v-else-if="order"><div class="admin-page-head"><div><p>ORDER</p><h1 class="ui-display">#{{order.order_number}}</h1><span>{{formatDateTime(order.created_at)}} · {{orderSourceLabel(order.source)}}</span></div><div class="admin-counter">{{formatMoney(order.total_minor,order.currency)}}</div></div><div class="order-quick-actions"><button v-if="form.status==='new'" type="button" @click="quickStatus('confirmed')">Confirm</button><button v-if="['new','confirmed'].includes(form.status)" type="button" @click="quickStatus('processing')">Start processing</button><button v-if="form.status!=='shipped'" type="button" @click="quickStatus('shipped')">Shipped</button><button v-if="form.status!=='completed'" type="button" @click="quickStatus('completed')">Complete</button><button v-if="form.payment_status!=='paid'" type="button" @click="markPaid">Mark as paid</button><button v-if="!['cancelled','completed'].includes(form.status)" class="is-danger" type="button" @click="quickStatus('cancelled')">Cancel</button></div><div v-if="error" class="admin-alert">{{error}}</div>
<div class="admin-order-layout"><div class="admin-order-main"><section class="admin-panel"><div class="admin-panel-head"><div><small>CUSTOMER</small><h2>Contact details</h2></div></div><div class="admin-form-grid admin-panel-body"><label class="admin-field"><span>Name</span><input v-model="form.customer_name"></label><label class="admin-field"><span>Phone</span><input v-model="form.customer_phone"></label><label class="admin-field"><span>Email</span><input v-model="form.customer_email" type="email"></label><label class="admin-field"><span>Source</span><select v-model="form.source"><option v-for="s in ['website','manual','phone','telegram','viber','instagram','other']" :key="s" :value="s">{{orderSourceLabel(s)}}</option></select></label></div></section>
<section class="admin-panel"><div class="admin-panel-head"><div><small>ITEMS</small><h2>Order items</h2></div></div><div class="order-items-read"><article v-for="item in order.items" :key="item.id"><div><strong>{{item.title}}</strong><small>{{item.sku}} · {{formatMoney(item.unit_price_minor,order.currency)}} × {{item.quantity}}</small></div><strong>{{formatMoney(item.line_total_minor,order.currency)}}</strong></article></div></section>
<section class="admin-panel"><div class="admin-panel-head"><div><small>SHIPPING</small><h2>Shipment & tracking</h2></div></div><div class="admin-form-grid admin-panel-body"><label class="admin-field"><span>Method</span><select v-model="form.shipping_method" @change="shippingChanged"><option value="">Not selected</option><option v-if="form.shipping_method&&!config.shipping_methods.some(m=>m.code===form.shipping_method)" :value="form.shipping_method">Saved method: {{form.shipping_method}}</option><option v-for="m in config.shipping_methods" :key="m.code" :value="m.code">{{m.name}}</option></select></label><label class="admin-field"><span>Carrier</span><input v-model="form.shipping_carrier"></label><label v-if="selectedShipping?.requires_city||form.shipping_city" class="admin-field"><span>City</span><input v-model="form.shipping_city"></label><label v-if="selectedShipping?.requires_branch||form.shipping_branch" class="admin-field"><span>Branch</span><input v-model="form.shipping_branch"></label><label v-if="selectedShipping?.requires_address||form.shipping_address" class="admin-field admin-field--wide"><span>Address</span><input v-model="form.shipping_address"></label><label class="admin-field admin-field--wide"><span>Tracking number</span><input v-model="form.tracking_number"></label></div></section>
<section class="admin-panel"><div class="admin-panel-head"><div><small>NOTES</small><h2>Notes</h2></div></div><div class="admin-panel-body"><label class="admin-field"><span>Customer note</span><textarea v-model="form.customer_note" rows="3"></textarea></label><label class="admin-field"><span>Internal note</span><textarea v-model="form.admin_note" rows="4"></textarea></label><label class="admin-field"><span>Status change note</span><input v-model="form.status_note"></label></div></section></div>
<aside class="admin-order-side"><section class="admin-panel admin-order-summary"><div class="admin-panel-head"><div><small>STATE</small><h2>Processing</h2></div></div><div class="admin-panel-body" style="padding-inline: 16px;"><label class="admin-field" style="margin: 12px 0;"><span>Status</span><select v-model="form.status"><option v-for="s in ['new','confirmed','processing','shipped','completed','cancelled','returned']" :key="s" :value="s">{{orderStatusLabel(s)}}</option></select></label><label class="admin-field" style="margin: 12px 0;"><span>Payment</span><select v-model="form.payment_status"><option v-for="s in ['unpaid','pending','paid','refunded']" :key="s" :value="s">{{paymentStatusLabel(s)}}</option></select></label><label class="admin-field" style="margin: 12px 0;"><span>Payment method</span><select v-model="form.payment_method"><option value="">Not selected</option><option v-if="form.payment_method&&!config.payment_methods.some(m=>m.code===form.payment_method)" :value="form.payment_method">Saved method: {{form.payment_method}}</option><option v-for="m in config.payment_methods" :key="m.code" :value="m.code">{{m.name}}</option></select></label><label class="admin-field" style="margin: 12px 0;"><span>Shipping amount</span><input v-model.number="form.shipping_amount" type="number" min="0"></label><label class="admin-field" style="margin: 12px 0;"><span>Discount amount</span><input v-model.number="form.discount_amount" type="number" min="0"></label><dl class="order-money" style="padding: 0;"><div><dt>Products</dt><dd>{{formatMoney(order.subtotal_minor,order.currency)}}</dd></div><div><dt>Total</dt><dd>{{formatMoney(Math.max(0,order.subtotal_minor-Math.round(form.discount_amount*100)+Math.round(form.shipping_amount*100)),order.currency)}}</dd></div></dl><button class="btn btn-primary" type="button" :disabled="saving" @click="save()"><AppIcon name="shield-check"/>{{saving?'Saving…':'Save changes'}}</button></div></section>
<section class="admin-panel"><div class="admin-panel-head"><div><small>HISTORY</small><h2>Status history</h2></div></div><div class="order-history"><article v-for="h in [...order.history].reverse()" :key="h.id"><span></span><div><strong>{{orderStatusLabel(h.to_status)}}</strong><small>{{formatDateTime(h.created_at)}}</small><p v-if="h.note">{{h.note}}</p></div></article></div></section></aside></div></template><div v-else class="admin-alert">{{error||'Order not found.'}}</div></section></template>
